from collections import Counter
def blocks(g):
    h,w=len(g),len(g[0]); res={}
    cnt=Counter(v for r in g for v in r)
    for c in cnt:
        if c==0: continue
        cells=[(i,j) for i in range(h) for j in range(w) if g[i][j]==c]
        i0,i1=min(i for i,j in cells),max(i for i,j in cells)
        j0,j1=min(j for i,j in cells),max(j for i,j in cells)
        bh,bw=i1-i0+1,j1-j0+1
        fill=len(cells)/(bh*bw)
        if fill>0.6 and len(cells)>6: res[c]=(bh,bw,len(cells))
    return res
