lib='''
def cells_of(grid, color):
    """All positions (i, j) holding the given color."""
    return [(i, j) for i, row in enumerate(grid) for j, v in enumerate(row) if v == color]

def bbox(cells):
    """(top, left, height, width) of the bounding box of a set of cells."""
    return (min(i for i, j in cells), min(j for i, j in cells),
            max(i for i, j in cells) - min(i for i, j in cells) + 1,
            max(j for i, j in cells) - min(j for i, j in cells) + 1)

def solid_blocks(grid, min_fill=0.6, min_size=7):
    """Map color -> (height, width, count) for each color forming one mostly-solid cluster."""
    from collections import Counter
    res = {}
    cnt = Counter(v for row in grid for v in row)
    for c, n in cnt.items():
        if c == 0:
            continue
        t, l, bh, bw = bbox(cells_of(grid, c))
        if n > min_size and n / (bh * bw) >= min_fill:
            res[c] = (bh, bw, n)
    return res

def solid_square(grid):
    """A k x k square of the largest solid block's color, k = the smallest block's shorter side."""
    bl = solid_blocks(grid)
    c = max(bl, key=lambda c: bl[c][2])
    k = min(min(bl[x][:2]) for x in bl)
    return [[c] * k for _ in range(k)]
